package com.hostelfind.service;
import com.hostelfind.dto.*; import com.hostelfind.model.*; import com.hostelfind.repository.UserRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class AuthService { private final UserRepository users; @Value("${hostelfind.allowed-email-domain:@hostel.edu}") private String allowedDomain; public AuthService(UserRepository users){this.users=users;} public User register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(!email.endsWith(allowedDomain))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Use your hostel email address");if(users.existsByEmailIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");User u=new User();u.setName(r.name().trim());u.setEmail(email);u.setPassword(r.password());u.setRole(Role.STUDENT);return users.save(u);} public User login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!u.getPassword().equals(r.password()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return u;} }
